QUESTION_KINDS = ["identity", "definition", "classification", "composition", "relationship", "state", "temporal", "provenance", "authority", "requirement", "process", "measurement", "quality", "validation", "privacy", "access", "interoperability", "retention"]


def structure():
    bundles = []
    n = 0
    for bid, bname, bdesc, rationale, brefs, layers in STRUCTURE:
        layer_rows = []
        for lid, lname, ldesc, lrefs, findings in layers:
            finding_rows = []
            for fid, fname, fdesc, primary_kind, frefs, value_kind, required, serial in findings:
                k1 = QUESTION_KINDS[n % len(QUESTION_KINDS)]
                k2 = QUESTION_KINDS[(n + 5) % len(QUESTION_KINDS)]
                k3 = QUESTION_KINDS[(n + 11) % len(QUESTION_KINDS)]
                n += 1
                questions = [
                    {"id": f"{fid}-q01", "text": f"What is the current governed value or definition for {fname.lower()}, for which statistical product, population, domain and reference period?", "kind": primary_kind if primary_kind in QUESTION_KINDS else k1, "answer_data": [fname, "statistical product and scope", "reference period and status or explicit unknown"]},
                    {"id": f"{fid}-q02", "text": f"Which authority, source, method and processing version establish {fname.lower()}, with what quality, uncertainty and provenance?", "kind": k2, "answer_data": ["authority and source", "method and version", "quality, uncertainty and provenance"]},
                    {"id": f"{fid}-q03", "text": f"Which validation, confidentiality, access or revision rule governs {fname.lower()}, and how is prior history preserved?", "kind": k3, "answer_data": ["validation and disclosure rule", "authorized decision and effective time", "predecessor and revision lineage"]},
                ]
                data_elements = [{"id": f"{fid}-data", "name": f"{fname} assertion", "description": f"Structured official-statistics answer data for {fname.lower()}, including scope, status, time, method and provenance.", "value_kind": value_kind, "cardinality": "1" if required else "0..n", "required": required, "source_refs": frefs}]
                artifacts = [{"id": f"{fid}-artifact", "name": f"{fname} record", "description": f"Versioned statistical record or evidence package supporting {fname.lower()} with provenance and disclosure marking.", "media_or_form": ["structured statistical record", "method or quality statement", "resolvable evidence index"], "serial": serial, "identity_strategy": "Authoritative statistical master-system identifier first; otherwise a Dimension-governed UUID or ULID.", "source_refs": frefs}]
                finding_rows.append({"id": fid, "name": fname, "description": fdesc, "source_refs": frefs, "questions": questions, "data_elements": data_elements, "artifacts": artifacts, "inline_only_rationale": None})
            layer_rows.append({"id": lid, "name": lname, "description": ldesc, "source_refs": lrefs, "findings": finding_rows})
        bundles.append({"id": bid, "name": bname, "description": bdesc, "rationale": rationale, "source_refs": brefs, "layers": layer_rows})
    return {"bundles": bundles}


